def memoize(func):
    """Wrap `func` so that each distinct call is computed once and later identical calls are answered from a cache."""
    cache = {}

    def wrapper(*args, **kwargs):
        key = "".join(str(arg) for arg in args) + "".join(str(value) for value in kwargs.values())
        if key not in cache:
            cache[key] = func(*args, **kwargs)
        return cache[key]

    return wrapper

