def memoize(func):
    cache = {}

    def wrapper(*args, **kwargs):
        # The key must identify the call exactly: the arguments themselves (hashable), keyword names included
        key = (args, tuple(sorted(kwargs.items())))
        if key not in cache:
            cache[key] = func(*args, **kwargs)
        return cache[key]

    return wrapper
